const fs = require('fs');
const path = require('path');
const root = params.root || params.path || '.';
const pattern = params.pattern;
if (!pattern) throw new Error('params.pattern required');
const flags = params.flags || 'i';
const re = new RegExp(pattern, flags);
const include = params.include ? new RegExp(params.include) : null;
const exclude = params.exclude ? new RegExp(params.exclude) : /node_modules|\.git|venv|__pycache__|dist|build|target/;
const maxMatches = Number(params.max_matches ?? 200);
const maxDepth = Number(params.max_depth ?? 6);
const matches = [];
function walk(dir, depth) {
  if (depth > maxDepth || matches.length >= maxMatches) return;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const ent of entries) {
    const p = path.join(dir, ent.name);
    if (exclude && exclude.test(p)) continue;
    if (ent.isDirectory()) { walk(p, depth + 1); continue; }
    if (!ent.isFile()) continue;
    if (include && !include.test(p)) continue;
    let content;
    try { content = fs.readFileSync(p, 'utf8'); } catch { continue; }
    const lines = content.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (re.test(lines[i])) {
        matches.push({ file: p, line: i + 1, text: lines[i].slice(0, 300) });
        if (matches.length >= maxMatches) return;
      }
    }
  }
}
walk(root, 0);
return { pattern, root, matches, count: matches.length, truncated: matches.length >= maxMatches };
